/bin/bash -lc "node --input-type=module - <<'NODE'
import { discountMinor } from './src/discount.js';
const cases = [
  ['threshold', 10000, 2026],
  ['just above', 10001, 2026],
  ['future member year', 10000, 2030],
  ['negative subtotal', -10000, 2020],
  ['missing memberSince', 10000, undefined],
  ['invalid memberSince', 10000, 'not-a-year'],
];
for (const [name, subtotal, since] of cases) {
  try { console.log(name, discountMinor(subtotal, since)); }
  catch (error) { console.log(name, "'`${error.name}: ${error.message}`); }
}
NODE
printf '"'%s\\n' '--- workspace status ---'; git status --short 2>/dev/null || true
printf '%s\\n' '--- all non-agent paths ---'; find . -path './.agent-input' -prune -o -type f -print | sort"

